def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_d = 0
    opp_d = 0
    bad = 0       # my C, opp D
    good = 0      # my D, opp C
    after_c_c = 0
    after_c_d = 0
    after_d_c = 0
    after_d_d = 0

    for i, (m, o) in enumerate(history):
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1
        if m == 'C' and o == 'D':
            bad += 1
        elif m == 'D' and o == 'C':
            good += 1

        if i > 0:
            pm = history[i - 1][0]
            if pm == 'C':
                if o == 'C':
                    after_c_c += 1
                else:
                    after_c_d += 1
            else:
                if o == 'C':
                    after_d_c += 1
                else:
                    after_d_d += 1

    after_c_tot = after_c_c + after_c_d
    after_d_tot = after_d_c + after_d_d
    fC = float(after_c_c + 1) / float(after_c_tot + 2)
    fD = float(after_d_c + 1) / float(after_d_tot + 2)

    recent6 = history[-6:]
    recent8 = history[-8:]
    recent_bad = sum(1 for m, o in recent6 if m == 'C' and o == 'D')
    recent_my_d = sum(1 for m, o in recent6 if m == 'D')
    recent_opp_d8 = sum(1 for m, o in recent8 if o == 'D')
    recent_good = sum(1 for m, o in recent8 if m == 'D' and o == 'C')

    last_me, last_opp = history[-1]

    # Sustained exploitation: punish clearly uncooperative behavior.
    if recent_bad >= 3 and recent_bad > recent_my_d + 1:
        return 'D'
    if bad >= 10 and bad > my_d + 4:
        return 'D'
    if opp_d >= 30 and opp_d * 3 >= n * 2 and recent_opp_d8 >= 5:
        return 'D'

    # Exploit unconditional or unusually forgiving cooperators.
    if after_d_tot > 0 and after_d_c > after_d_d:
        if opp_d == 0 and recent_bad == 0:
            return 'D'
        if after_d_c >= 2 and recent_good >= 2:
            if recent_opp_d8 == 0 and recent_bad == 0 and opp_d <= 2:
                if rng.random() < 0.5:
                    return 'D'

    # If defection is not strongly retaliated, bias toward D.
    if after_c_tot >= 4 and fC <= 0.68 and fD + 0.28 >= fC and recent_bad <= 2:
        return 'D'

    # Predict opponent's current move using transition statistics.
    if last_me == 'D':
        p = fD
    else:
        p = fC

    if p < 0.28:
        # Likely D: restore if it looks like retaliation we can end.
        if fC >= 0.55 and recent_my_d > 0 and recent_bad <= recent_my_d + 1:
            return 'C'
        return 'D'

    # Opponent defected last.
    if last_opp == 'D':
        # Usually provoked; cooperate to avoid long defection spirals.
        if recent_my_d > 0 and recent_bad <= recent_my_d + 1 and opp_d * 3 <= n * 2:
            if rng.random() < 0.12:
                return 'D'
            return 'C'

        # Unprovoked or too costly: punish, with slight forgiveness.
        if opp_d * 4 < n and recent_bad <= 1 and rng.random() < 0.18:
            return 'C'
        return 'D'

    # Opponent cooperated last.  One careful probe against clean cooperation.
    streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C' and history[i][1] == 'C':
            streak += 1
        else:
            break

    if my_d == 0 and opp_d == 0 and streak >= 10 and n < 92:
        return 'D'

    return 'C'
